/*
 * Theme zero — the @bydiorama/ui token layer and the Tailwind v4 theme that
 * maps utilities onto it. GENERATED by scripts/build-theme-css.mjs from
 * @bydiorama/tokens; do not edit — reinstall the `theme-zero-css` item.
 *
 * Import it once, after `@import "tailwindcss";`, in the stylesheet
 * Tailwind compiles. Light and dark follow prefers-color-scheme.
 */

@theme inline {

  /* Colour roles. */
  --color-ink-primary: var(--ui-text-primary);
  --color-ink-secondary: var(--ui-text-secondary);
  --color-ink-muted: var(--ui-text-muted);
  --color-ink-disabled: var(--ui-text-disabled);
  --color-ink-placeholder: var(--ui-text-placeholder);
  --color-ink-inverse: var(--ui-text-inverse);
  --color-ink-inverse-muted: var(--ui-text-inverse-muted);
  --color-ink-link: var(--ui-text-link);
  --color-ink-link-hover: var(--ui-text-link-hover);
  --color-ink-on-accent: var(--ui-text-on-accent);
  --color-ink-on-emphasis: var(--ui-text-on-emphasis);
  --color-ink-on-muted: var(--ui-text-on-muted);
  --color-ink-on-danger-solid: var(--ui-text-on-danger-solid);
  --color-ink-on-media: var(--ui-text-on-media);
  --color-ink-on-media-muted: var(--ui-text-on-media-muted);
  --color-base: var(--ui-bg-base);
  --color-surface: var(--ui-bg-surface);
  --color-elevated: var(--ui-bg-elevated);
  --color-sunken: var(--ui-bg-sunken);
  --color-field: var(--ui-bg-field);
  --color-field-disabled: var(--ui-bg-field-disabled);
  --color-field-chrome: var(--ui-bg-field-chrome);
  --color-field-chrome-disabled: var(--ui-bg-field-chrome-disabled);
  --color-affix: var(--ui-bg-affix);
  --color-affix-floor: var(--ui-bg-affix-floor);
  --color-glass: var(--ui-bg-glass);
  --color-glass-floor: var(--ui-bg-glass-floor);
  --color-muted: var(--ui-bg-muted);
  --color-overlay: var(--ui-bg-overlay);
  --color-hover: var(--ui-bg-hover);
  --color-active: var(--ui-bg-active);
  --color-selected: var(--ui-bg-selected);
  --color-accent: var(--ui-bg-accent);
  --color-accent-hover: var(--ui-bg-accent-hover);
  --color-accent-active: var(--ui-bg-accent-active);
  --color-accent-subtle: var(--ui-bg-accent-subtle);
  --color-accent-subtle-hover: var(--ui-bg-accent-subtle-hover);
  --color-accent-legible: var(--ui-bg-accent-legible);
  --color-media: var(--ui-bg-media);
  --color-media-floor: var(--ui-bg-media-floor);
  --color-emphasis: var(--ui-bg-emphasis);
  --color-emphasis-hover: var(--ui-bg-emphasis-hover);
  --color-emphasis-active: var(--ui-bg-emphasis-active);
  --color-inverse: var(--ui-bg-inverse);
  --color-inverse-hover: var(--ui-bg-inverse-hover);
  --color-inverse-active: var(--ui-bg-inverse-active);
  --color-danger-solid: var(--ui-bg-danger-solid);
  --color-edge-subtle: var(--ui-border-subtle);
  --color-edge-default: var(--ui-border-default);
  --color-edge-control: var(--ui-border-control);
  --color-edge-strong: var(--ui-border-strong);
  --color-edge-focus: var(--ui-border-focus);
  --color-focus-ring: var(--ui-focus-ring-color);
  --color-success: var(--ui-intent-success-fg);
  --color-success-subtle: var(--ui-intent-success-bg);
  --color-warning: var(--ui-intent-warning-fg);
  --color-warning-subtle: var(--ui-intent-warning-bg);
  --color-danger: var(--ui-intent-danger-fg);
  --color-danger-subtle: var(--ui-intent-danger-bg);
  --color-danger-subtle-hover: var(--ui-intent-danger-bg-hover);
  --color-danger-border: var(--ui-intent-danger-border);
  --color-ink-on-danger-subtle: var(--ui-text-on-danger-subtle);
  --color-info: var(--ui-intent-info-fg);
  --color-info-subtle: var(--ui-intent-info-bg);
  --color-data-informational-fg: var(--ui-data-informational-fg);
  --color-data-informational-bg: var(--ui-data-informational-bg);
  --color-data-informational-solid: var(--ui-data-informational-solid);
  --color-data-commercial-fg: var(--ui-data-commercial-fg);
  --color-data-commercial-bg: var(--ui-data-commercial-bg);
  --color-data-commercial-solid: var(--ui-data-commercial-solid);
  --color-data-transactional-fg: var(--ui-data-transactional-fg);
  --color-data-transactional-bg: var(--ui-data-transactional-bg);
  --color-data-transactional-solid: var(--ui-data-transactional-solid);
  --color-data-navigational-fg: var(--ui-data-navigational-fg);
  --color-data-navigational-bg: var(--ui-data-navigational-bg);
  --color-data-navigational-solid: var(--ui-data-navigational-solid);
  --color-nav: var(--ui-nav-bg);
  --color-ink-nav: var(--ui-nav-ink);
  --color-ink-nav-muted: var(--ui-nav-ink-muted);
  --color-ink-nav-disabled: var(--ui-nav-ink-disabled);
  --color-edge-nav: var(--ui-nav-border);
  --color-nav-hover: var(--ui-nav-hover-bg);
  --color-nav-active: var(--ui-nav-active-bg);
  --color-ink-nav-active: var(--ui-nav-active-ink);
  --color-scrim: var(--ui-scrim);

  /* Type scale — size plus weight, leading and tracking per role. */
  --text-display-lg: var(--ui-text-display-lg);
  --text-display-lg--font-weight: var(--ui-text-display-lg-weight);
  --text-display-lg--line-height: var(--ui-text-display-lg-leading);
  --text-display-lg--letter-spacing: var(--ui-text-display-lg-tracking);
  --text-display-md: var(--ui-text-display-md);
  --text-display-md--font-weight: var(--ui-text-display-md-weight);
  --text-display-md--line-height: var(--ui-text-display-md-leading);
  --text-display-md--letter-spacing: var(--ui-text-display-md-tracking);
  --text-title-lg: var(--ui-text-title-lg);
  --text-title-lg--font-weight: var(--ui-text-title-lg-weight);
  --text-title-lg--line-height: var(--ui-text-title-lg-leading);
  --text-title-lg--letter-spacing: var(--ui-text-title-lg-tracking);
  --text-title-md: var(--ui-text-title-md);
  --text-title-md--font-weight: var(--ui-text-title-md-weight);
  --text-title-md--line-height: var(--ui-text-title-md-leading);
  --text-title-md--letter-spacing: var(--ui-text-title-md-tracking);
  --text-title-sm: var(--ui-text-title-sm);
  --text-title-sm--font-weight: var(--ui-text-title-sm-weight);
  --text-title-sm--line-height: var(--ui-text-title-sm-leading);
  --text-title-sm--letter-spacing: var(--ui-text-title-sm-tracking);
  --text-body-lg: var(--ui-text-body-lg);
  --text-body-lg--font-weight: var(--ui-text-body-lg-weight);
  --text-body-lg--line-height: var(--ui-text-body-lg-leading);
  --text-body-lg--letter-spacing: var(--ui-text-body-lg-tracking);
  --text-body-md: var(--ui-text-body-md);
  --text-body-md--font-weight: var(--ui-text-body-md-weight);
  --text-body-md--line-height: var(--ui-text-body-md-leading);
  --text-body-md--letter-spacing: var(--ui-text-body-md-tracking);
  --text-body-sm: var(--ui-text-body-sm);
  --text-body-sm--font-weight: var(--ui-text-body-sm-weight);
  --text-body-sm--line-height: var(--ui-text-body-sm-leading);
  --text-body-sm--letter-spacing: var(--ui-text-body-sm-tracking);
  --text-label-md: var(--ui-text-label-md);
  --text-label-md--font-weight: var(--ui-text-label-md-weight);
  --text-label-md--line-height: var(--ui-text-label-md-leading);
  --text-label-md--letter-spacing: var(--ui-text-label-md-tracking);
  --text-label-sm: var(--ui-text-label-sm);
  --text-label-sm--font-weight: var(--ui-text-label-sm-weight);
  --text-label-sm--line-height: var(--ui-text-label-sm-leading);
  --text-label-sm--letter-spacing: var(--ui-text-label-sm-tracking);
  --text-caption: var(--ui-text-caption);
  --text-caption--font-weight: var(--ui-text-caption-weight);
  --text-caption--line-height: var(--ui-text-caption-leading);
  --text-caption--letter-spacing: var(--ui-text-caption-tracking);
  --text-button-lg: var(--ui-text-button-lg);
  --text-button-lg--font-weight: var(--ui-text-button-lg-weight);
  --text-button-lg--line-height: var(--ui-text-button-lg-leading);
  --text-button-lg--letter-spacing: var(--ui-text-button-lg-tracking);
  --text-button-sm: var(--ui-text-button-sm);
  --text-button-sm--font-weight: var(--ui-text-button-sm-weight);
  --text-button-sm--line-height: var(--ui-text-button-sm-leading);
  --text-button-sm--letter-spacing: var(--ui-text-button-sm-tracking);

  /* radius namespace. */
  --radius-sm: var(--ui-radius-sm);
  --radius-md: var(--ui-radius-md);
  --radius-lg: var(--ui-radius-lg);
  --radius-xl: var(--ui-radius-xl);
  --radius-2xl: var(--ui-radius-2xl);
  --radius-full: var(--ui-radius-full);

  /* shadow namespace. */
  --shadow-sm: var(--ui-shadow-sm);
  --shadow-md: var(--ui-shadow-md);
  --shadow-lg: var(--ui-shadow-lg);
  --shadow-xl: var(--ui-shadow-xl);
  --shadow-sm-up: var(--ui-shadow-sm-up);
  --shadow-md-up: var(--ui-shadow-md-up);
  --shadow-lg-up: var(--ui-shadow-lg-up);
  --shadow-xl-up: var(--ui-shadow-xl-up);

  /* font namespace. */
  --font-body: var(--ui-font-body);
  --font-display: var(--ui-font-display);

  /* Chrome dimensions. */
  --spacing-nav: var(--ui-nav-width);
  --spacing-nav-rail: var(--ui-nav-rail-width);
  --spacing-dialog-md: var(--ui-dialog-width-md);
  --spacing-dialog-lg: var(--ui-dialog-width-lg);

  /* Control sizing. */
  --spacing-control-sm: var(--ui-control-sm-height);
  --spacing-control-md: var(--ui-control-md-height);
  --spacing-control-lg: var(--ui-control-lg-height);
  --spacing-control-inset-sm: var(--ui-control-sm-inset);
  --spacing-control-inset-md: var(--ui-control-md-inset);
  --spacing-control-inset-lg: var(--ui-control-lg-inset);
  --spacing-field-sm: var(--ui-field-sm-height);
  --spacing-field-md: var(--ui-field-md-height);
  --spacing-field-lg: var(--ui-field-lg-height);
  --spacing-field-inset-sm: var(--ui-field-sm-inset);
  --spacing-field-inset-md: var(--ui-field-md-inset);
  --spacing-field-inset-lg: var(--ui-field-lg-inset);

  /* Stroke widths. */
  --default-border-width: var(--ui-stroke-default);
  --default-ring-width: var(--ui-stroke-default);
  --default-outline-width: var(--ui-stroke-default);
  --border-width-hairline: var(--ui-stroke-hairline);
  --border-width-thick: var(--ui-stroke-thick);
  --ring-width-hairline: var(--ui-stroke-hairline);
  --ring-width-thick: var(--ui-stroke-thick);
  --outline-width-hairline: var(--ui-stroke-hairline);
  --outline-width-thick: var(--ui-stroke-thick);
  --outline-width-focus: var(--ui-focus-ring-width);
  --outline-offset-focus: var(--ui-focus-ring-offset);

  /* Spacing — the base scale only; stack/inline/inset intents stay CSS-side. */
  --spacing-xs: var(--ui-space-xs);
  --spacing-sm: var(--ui-space-sm);
  --spacing-md: var(--ui-space-md);
  --spacing-lg: var(--ui-space-lg);
  --spacing-xl: var(--ui-space-xl);
  --spacing-2xl: var(--ui-space-2xl);
  --spacing-3xl: var(--ui-space-3xl);
  --spacing-4xl: var(--ui-space-4xl);

  /* Typography attributes. */
  --font-weight-regular: var(--ui-weight-regular);
  --font-weight-book: var(--ui-weight-book);
  --font-weight-medium: var(--ui-weight-medium);
  --font-weight-semibold: var(--ui-weight-semibold);
  --font-weight-bold: var(--ui-weight-bold);
  --tracking-tight: var(--ui-tracking-tight);
  --tracking-normal: var(--ui-tracking-normal);
  --leading-flat: var(--ui-leading-flat);
  --leading-tight: var(--ui-leading-tight);
  --leading-snug: var(--ui-leading-snug);
  --leading-normal: var(--ui-leading-normal);
  --leading-relaxed: var(--ui-leading-relaxed);
}


:root {
  color-scheme: light dark;

  /* Structural — identical in every theme. */
  --ui-space-xs: 0.25rem;
  --ui-space-sm: 0.5rem;
  --ui-space-md: 0.75rem;
  --ui-space-lg: 1rem;
  --ui-space-xl: 1.5rem;
  --ui-space-2xl: 2rem;
  --ui-space-3xl: 3rem;
  --ui-space-4xl: 4rem;
  --ui-space-stack-xs: var(--ui-space-xs);
  --ui-space-stack-sm: var(--ui-space-sm);
  --ui-space-stack-md: var(--ui-space-lg);
  --ui-space-stack-lg: var(--ui-space-xl);
  --ui-space-stack-xl: var(--ui-space-3xl);
  --ui-space-stack-2xl: var(--ui-space-4xl);
  --ui-space-inline-xs: var(--ui-space-xs);
  --ui-space-inline-sm: var(--ui-space-sm);
  --ui-space-inline-md: var(--ui-space-md);
  --ui-space-inline-lg: var(--ui-space-lg);
  --ui-space-inset-xs: var(--ui-space-sm);
  --ui-space-inset-sm: var(--ui-space-md);
  --ui-space-inset-md: var(--ui-space-lg);
  --ui-space-inset-lg: var(--ui-space-xl);
  --ui-space-inset-xl: var(--ui-space-2xl);
  --ui-leading-flat: 1;
  --ui-leading-tight: 1.25;
  --ui-leading-snug: 1.3;
  --ui-leading-normal: 1.35;
  --ui-leading-relaxed: 1.55;
  --ui-duration-fast: 120ms;
  --ui-duration-base: 200ms;
  --ui-duration-slow: 320ms;
  --ui-duration-enter: 400ms;
  --ui-duration-loop: 2000ms;
  --ui-ease-default: cubic-bezier(0.2, 0, 0, 1);
  --ui-ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ui-ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ui-ease-spring: cubic-bezier(0.22, 1, 0.36, 1);
  --ui-motion-micro: var(--ui-duration-fast) var(--ui-ease-out);
  --ui-motion-standard: var(--ui-duration-base) var(--ui-ease-default);
  --ui-motion-deliberate: var(--ui-duration-slow) var(--ui-ease-default);
  --ui-motion-choreographed: var(--ui-duration-enter) var(--ui-ease-spring);
  --ui-press-scale: 0.96;
  --ui-stagger-step: 100ms;
  --ui-control-sm-height: 1.5rem;
  --ui-control-sm-inset: var(--ui-space-sm);
  --ui-control-md-height: 2rem;
  --ui-control-md-inset: var(--ui-space-md);
  --ui-control-lg-height: 2.75rem;
  --ui-control-lg-inset: var(--ui-space-lg);
  --ui-field-sm-height: 2rem;
  --ui-field-sm-inset: var(--ui-space-sm);
  --ui-field-md-height: 2.5rem;
  --ui-field-md-inset: var(--ui-space-sm);
  --ui-field-lg-height: 3rem;
  --ui-field-lg-inset: var(--ui-space-md);
  --ui-hit-area-min: 24px;
  --ui-hit-area-touch: 44px;
  --ui-measure-prose: 70ch;
  --ui-measure-narrative: 60ch;
  --ui-measure-dense: 90ch;
  --ui-z-below: -1;
  --ui-z-base: 0;
  --ui-z-sticky: 100;
  --ui-z-overlay: 1000;
  --ui-z-modal: 1100;
  --ui-z-toast: 1200;
  --ui-z-dropdown: 1300;
  --ui-z-tooltip: 1400;

  /* Scheme-varying, brand-invariant. */
  --ui-scrim: light-dark(rgba(152, 145, 138, 0.16), rgba(0, 0, 0, 0.55));
  --ui-selection-bg: light-dark(rgba(16, 16, 20, 0.12), rgba(255, 255, 255, 0.22));
  --ui-selection-fg: light-dark(#101014, #ffffff);

  /* Theme. */
  --ui-text-primary: light-dark(#1D1B19, #FAF7F3);
  --ui-text-secondary: light-dark(#2F2C29, #D6D1CB);
  --ui-text-muted: light-dark(#69635D, #A69F98);
  --ui-text-disabled: light-dark(#B7B0A9, #5F5A54);
  --ui-text-placeholder: light-dark(#69635D, #948D86);
  --ui-text-inverse: light-dark(#F6F3F0, #1D1B19);
  --ui-text-inverse-muted: light-dark(#B7B0A9, #69635D);
  --ui-text-link: light-dark(#1B6C84, #9EDBF3);
  --ui-text-link-hover: light-dark(#134553, #D2EBF8);
  --ui-text-on-accent: #1D1B19;
  --ui-text-on-emphasis: light-dark(#FFFFFF, #1D1B19);
  --ui-text-on-muted: light-dark(#1D1B19, #FAF7F3);
  --ui-text-on-danger-solid: light-dark(#FFFFFF, #FAF7F3);
  --ui-text-on-media: #F6F3F0;
  --ui-text-on-media-muted: #DAD4CE;
  --ui-bg-base: light-dark(#FFFFFF, #171411);
  --ui-bg-surface: light-dark(#FDFCFB, #1E1B18);
  --ui-bg-elevated: light-dark(#F6F3F0, #2A2724);
  --ui-bg-sunken: light-dark(#EDE8E3, #383531);
  --ui-bg-field: light-dark(#FFFFFF, #120F0C);
  --ui-bg-field-disabled: light-dark(#EDE8E3, #221F1C);
  --ui-bg-field-chrome: light-dark(#EDE8E3, #1E1B18);
  --ui-bg-field-chrome-disabled: light-dark(#DAD4CE, #2A2724);
  --ui-bg-affix: light-dark(rgba(255, 255, 255, 0.9), rgba(23, 20, 17, 0.9));
  --ui-bg-affix-floor: light-dark(#e6e6e6, #2e2b29);
  --ui-bg-glass: light-dark(rgba(253, 252, 251, 0.9), rgba(30, 27, 24, 0.92));
  --ui-bg-glass-floor: light-dark(#e4e3e2, #383533);
  --ui-bg-muted: light-dark(#EDE8E3, #1E1B18);
  --ui-bg-overlay: light-dark(#DAD4CE, rgba(0, 0, 0, 0.55));
  --ui-bg-hover: light-dark(#EDE8E3, #2E2B28);
  --ui-bg-active: light-dark(#DAD4CE, #33302D);
  --ui-bg-selected: light-dark(#EDE8E3, #2C2926);
  --ui-bg-accent: #9EDBF3;
  --ui-bg-accent-hover: #79B8D3;
  --ui-bg-accent-active: #5799B1;
  --ui-bg-accent-subtle: light-dark(#D2EBF8, rgba(158, 219, 243, 0.1));
  --ui-bg-accent-subtle-hover: light-dark(#C3DBE7, rgba(158, 219, 243, 0.16));
  --ui-bg-accent-legible: light-dark(#518ca2, #9EDBF3);
  --ui-bg-media: #1D1B19;
  --ui-bg-media-floor: #5c5b59;
  --ui-bg-emphasis: light-dark(#1D1B19, #F6F3F0);
  --ui-bg-emphasis-hover: light-dark(#2F2C29, #EDE8E3);
  --ui-bg-emphasis-active: light-dark(#423E3A, #DAD4CE);
  --ui-bg-inverse: light-dark(#1D1B19, #F6F3F0);
  --ui-bg-inverse-hover: light-dark(#2F2C29, #EDE8E3);
  --ui-bg-inverse-active: light-dark(#423E3A, #DAD4CE);
  --ui-bg-danger-solid: light-dark(#A9441F, #a9441f);
  --ui-gradient-brand: linear-gradient(in oklab 270deg, #9EDBF3 0%, #D0D4F7 50%, #F6CEC2 100%);
  --ui-gradient-accent: linear-gradient(in oklab 90deg, #9EDBF3 50%, #79B8D3 100%);
  --ui-border-subtle: light-dark(#DAD4CE, #302D2A);
  --ui-border-default: light-dark(#B7B0A9, #45423E);
  --ui-border-control: light-dark(#98918A, #857E77);
  --ui-border-strong: light-dark(#69635D, #A69F98);
  --ui-border-focus: light-dark(#1B6C84, #9EDBF3);
  --ui-focus-ring-color: light-dark(#1B6C84, #9EDBF3);
  --ui-focus-ring: 0 0 0 2px light-dark(#FFFFFF, #171411), 0 0 0 4px light-dark(#1B6C84, #9EDBF3);
  --ui-focus-ring-width: 2px;
  --ui-focus-ring-offset: 2px;
  --ui-intent-success-fg: light-dark(#246E41, #B3DFA4);
  --ui-intent-success-bg: light-dark(#D6EFCB, #243125);
  --ui-intent-warning-fg: light-dark(#8F5426, #F4BA8E);
  --ui-intent-warning-bg: light-dark(#F8E7D9, #3a2b1f);
  --ui-intent-danger-fg: light-dark(#A9441F, #EF9E80);
  --ui-intent-danger-bg: light-dark(#F9E2DB, #3b2920);
  --ui-intent-danger-bg-hover: light-dark(#F6CEC2, #4a3024);
  --ui-intent-danger-border: light-dark(#F6CEC2, rgba(212, 116, 74, 0.36));
  --ui-text-on-danger-subtle: light-dark(#6A2C18, #F6CEC2);
  --ui-intent-info-fg: light-dark(#1B6C84, #9EDBF3);
  --ui-intent-info-bg: light-dark(#D2EBF8, #272f30);
  --ui-data-informational-fg: light-dark(#1B6C84, #9EDBF3);
  --ui-data-informational-bg: light-dark(#D2EBF8, rgba(27, 108, 132, 0.14));
  --ui-data-informational-solid: light-dark(#5799B1, #79B8D3);
  --ui-data-commercial-fg: light-dark(#8F5426, #F4BA8E);
  --ui-data-commercial-bg: light-dark(#F8E7D9, rgba(143, 84, 38, 0.14));
  --ui-data-commercial-solid: light-dark(#CC8043, #E0A473);
  --ui-data-transactional-fg: light-dark(#246E41, #B3DFA4);
  --ui-data-transactional-bg: light-dark(#D6EFCB, rgba(36, 110, 65, 0.14));
